/* eslint-disable react-hooks/exhaustive-deps */
import { useCallback } from "react";
import { Modal, Select, Form, Button } from 'antd'
import WalletModalWrapper from '../style'
import { imageUrl } from '../../constant'

const { CloseIcon } = imageUrl

const { Option } = Select

const AddWalletModal = ({
    isOpen, 
    closeModal, 
    form, 
    masterListData,
    getMasterList,
    addWalletRequest,
    ADD_WALLET_LOADER
}) => {

  const { getFieldDecorator, getFieldValue } = form

  const handlePartnerChange = useCallback(
    (partnerCode = "") => {
      getMasterList({query: { 
        partnerCode: partnerCode
      }})
      form.resetFields(["providerCode", "productCode", "packageCode"])
    },
    []
  )
  const handleProviderChange = useCallback(
    (providerCode = "") => {
      getMasterList({query: { 
        partnerCode: getFieldValue('partnerCode'),
        providerCode: providerCode,
      }})
      form.resetFields([ "productCode", "packageCode"])
    },
    []
  )
  const handleProductChange = useCallback(
    (productCode = []) => {
      getMasterList({query: { 
        partnerCode: getFieldValue('partnerCode'),
        productCode: productCode,
        providerCode: getFieldValue('providerCode'),
      }})
      form.resetFields(["packageCode"])
    },
    []
  )
  
  const validateForm = useCallback(async () => {
    return new Promise((resolve) => {
      form.validateFields((error) => {
        resolve(!error)
      })
    })
  }, [form])

  const handleSubmit = useCallback(async (e) => {
    e.preventDefault()
    const valid = await validateForm()
    if (!valid) return
    const formValues = {
      ...form.getFieldsValue()
    }
    
    addWalletRequest({body: {
      partner_code: formValues.partnerCode,
      product_code: formValues.productCode,
      provider_code: formValues.providerCode,
      package_code_list: formValues.packageCode
    }})
  }, [form, validateForm, addWalletRequest])
  return (
    <Modal
      title=""
      visible={isOpen}
      footer={null}
      closable={false}
      onCancel={closeModal}
      bodyStyle={{padding: 0}}
      afterClose={() => form.resetFields()}
    >
      <WalletModalWrapper>
        <div className="title">
          <strong>Add New Wallet</strong>
          <img
            onClick={closeModal}
            src={CloseIcon}
            className="close-icon"
            alt="close"
          />
        </div>
        <Form onSubmit={handleSubmit}>
          <label>Select Partner</label>
          <Form.Item>
            {getFieldDecorator("partnerCode", {
              rules: [{required: true, message: "Please select partner"}]
            })(
              <Select
                showSearch
                allowClear
                placeholder="Partner"
                onChange={handlePartnerChange}
              >
                {masterListData?.partner_code_list?.map((value) => (
                  <Option key={value} value={value}>
                    {value}
                  </Option>
                ))}
              </Select>
            )}
          </Form.Item>
          <label>Select Provider</label>
          <Form.Item>
            {getFieldDecorator("providerCode", {
              rules: [{required: true, message: "Please select provider"}]
            })(
              <Select
                showSearch
                placeholder="Provider"
                allowClear
                onChange={handleProviderChange}
                disabled={!getFieldValue('partnerCode')}
              >
                {masterListData?.provider_code_list?.map((value) => (
                  <Option key={value} value={value}>
                    {value}
                  </Option>
                ))}
              </Select>
            )}
          </Form.Item>
          <label>Select Product</label>
          <Form.Item>
            {getFieldDecorator("productCode", {
              rules: [{required: true, message: "Please select Product"}]
            })(
              <Select
                showSearch
                placeholder="Product"
                allowClear
                disabled={!getFieldValue('providerCode')}
                onChange={handleProductChange}
              >
                {masterListData?.partner_product_details?.map((value) => (
                  <Option key={value.name} value={value.name}>
                    {value.display_name}
                  </Option>
                ))}
              </Select>
            )}
          </Form.Item>
          <label>Select Package</label>
          <Form.Item>
            {getFieldDecorator("packageCode", {
              rules: [{required: true, message: "Please select Package"}]
            })(
              <Select
                showSearch
                allowClear
                placeholder="Package"
                mode="multiple"
                disabled={!getFieldValue('productCode')}
              >
                {masterListData?.package_code_list?.map((value) => (
                  <Option key={value} value={value}>
                    {value}
                  </Option>
                ))}
              </Select>
            )}
          </Form.Item>
          <Button
            key="submit"
            type="primary"
            htmlType="submit"
            loading={!!ADD_WALLET_LOADER}
            className="form-submit"
          >
            Submit
          </Button>
        </Form>
      </WalletModalWrapper>
    </Modal>
  )
}


const WrappedForm = Form.create({})(AddWalletModal)

export default WrappedForm
