/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect, useCallback } from 'react'
import { Form, Icon, Row, Col, Spin, Tag, Divider, notification } from 'antd'
import QueryString from 'query-string'
import {
  useLoaderContextValue,
  useErrorContextValue,
  resetError
} from '@pasarpolis/common-react-hooks'

import { WalletListFilterKeyMap, imageUrl, currencyChange } from '../../constant'
import {
  FilterSelectOption,
  FilterInput
} from '../../../../../components/tables/helperCells'
import LayoutContentWrapper from '../../../../../components/utility/layoutWrapper'
import TableWrapper from '../../pagination.style'
import WalletListWrapper from './style'
import QuerySearchBuilder from '../../../../../helpers/querySearchBuilder'
import AddWalletModal from '../../component/addWalletModal'
import PermissionCheckerV2 from '../../../../../components/permissionCheckerV2'
import {
  useGetWalletList,
  useGetMasterList,
  useAddWallet,
  useResetState
} from '../../state/hooks/useWalletContext'

const { FilteredIcon, WalletIcon } = imageUrl

const Wallet = ({ location, history }) => {
  const [filterActive, setFilterActive] = useState(false)
  const [searchTextQuery, setSearchTextQuery] = useState({})
  const [appliedFilter, setAppliedFilter] = useState({})
  const [isAddModalVisible, showAddWalletModal] = useState(false)
  const [{ getWalletListData = {} }, getWalletListRequest] = useGetWalletList()
  const [{ getMasterListData = {} }, getMasterListRequest] = useGetMasterList()
  const [, addWalletRequest] = useAddWallet()
  const [resetState] = useResetState()
  const [{ GET_WALLET_LIST_LOADER, GET_MASTER_LIST_LOADER, ADD_WALLET_LOADER }] =
    useLoaderContextValue()
  const [
    {
      GET_WALLET_LIST_ERROR = '',
      GET_MASTER_LIST_ERROR = '',
      ADD_WALLET_ERROR = '',
      getWalletListStatus,
      getMasterListStatus,
      addWalletStatus,
      addWalletErrorData
    },
    dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    const querySearch = QueryString.parse(location?.search)
    fetch(querySearch)
    if (querySearch.sort) {
      delete querySearch.sort
    }
    setSearchTextQuery({ ...querySearch })
    setAppliedFilter({ ...querySearch })
    getMasterListRequest({
      query: {
        partnerCode: querySearch.partner_code,
        productCode: querySearch.product_code,
        packageCode: querySearch.product_code,
        providerCode: querySearch.provider_code
      }
    })
    return () => resetState(['getWalletListData'])
  }, [])

  // Error handling notify error status
  useEffect(() => {
    if (GET_WALLET_LIST_ERROR) {
      getWalletListStatus && notification.error({ message: getWalletListStatus })
      dispatchError(
        resetError({
          GET_WALLET_LIST_ERROR: false,
          getWalletListStatus: ''
        })
      )
    } else if (GET_MASTER_LIST_ERROR) {
      getMasterListStatus && notification.error({ message: getMasterListStatus })
      dispatchError(
        resetError({
          GET_MASTER_LIST_ERROR: false,
          getMasterListStatus: ''
        })
      )
    } else if (ADD_WALLET_ERROR) {
      if (
        addWalletErrorData?.errors &&
        addWalletErrorData?.errors.length &&
        addWalletErrorData?.errors[0]?.message
      ) {
        addWalletErrorData?.errors[0]?.message &&
          notification.error({ message: addWalletErrorData?.errors[0]?.message })
      } else {
        addWalletStatus && notification.error({ message: addWalletStatus })
      }
      dispatchError(
        resetError({
          ADD_WALLET_ERROR: false,
          addWalletStatus: '',
          addWalletErrorData: ''
        })
      )
    } else if (!ADD_WALLET_ERROR && addWalletStatus === 'success') {
      addWalletStatus && notification.success({ message: addWalletStatus })
      showAddWalletModal(false)
      const querySearch = QueryString.parse(location?.search)
      fetch(querySearch)
      dispatchError(
        resetError({
          addWalletStatus: ''
        })
      )
    }
  }, [
    GET_WALLET_LIST_ERROR,
    GET_MASTER_LIST_ERROR,
    ADD_WALLET_ERROR,
    getWalletListStatus,
    getMasterListStatus,
    addWalletStatus,
    addWalletErrorData
  ])

  const renderTitle = useCallback((titleClass, text) => {
    return (
      <div className={titleClass}>
        <span>{text}</span>
      </div>
    )
  }, [])

  const onInputChange = useCallback(
    (value, identifier) => {
      setSearchTextQuery({
        ...searchTextQuery,
        [identifier]: value
      })
    },
    [searchTextQuery, setSearchTextQuery]
  )

  const onSearch = useCallback(
    (e, key) => {
      e.preventDefault()
      getMasterListRequest({
        query: {
          partnerCode: searchTextQuery.partner_code,
          productCode: searchTextQuery.product_code,
          packageCode: searchTextQuery.package_code,
          providerCode: searchTextQuery.provider_code
        }
      })

      const searchText = { ...searchTextQuery, page: 1 }
      const search = QuerySearchBuilder(searchText)
      history.push({ pathname: location?.pathname, search })
      fetch(searchText)
      setFilterActive({ ...filterActive, [key]: false })
      setAppliedFilter(searchTextQuery)
    },
    [searchTextQuery, filterActive]
  )

  const renderIcon = useCallback(() => {
    return (
      <div className='filter-icon-wrapper'>
        <img src={FilteredIcon} className='filter-icon' alt='' />
      </div>
    )
  }, [])

  const FilterDropdown = useCallback(
    (identifier, listKey, renderOption) => {
      return (
        <FilterSelectOption
          searchText={
            searchTextQuery[identifier]
              ? searchTextQuery[identifier]
              : undefined
          }
          onInputChange={(e) => onInputChange(e.target.value, identifier)}
          onSearch={(e) => onSearch(e, identifier)}
          optionData={
            getMasterListData && Array.isArray(getMasterListData[listKey])
              ? getMasterListData[listKey]
              : []
          }
          renderOption={
            identifier === 'product_code'
              ? (data) => {
                  return data.map((val) => (
                    <option key={val.name} value={val.name}>
                      {val.display_name}
                    </option>
                  ))
                }
              : undefined
          }
        />
      )
    },
    [searchTextQuery, getMasterListData, onInputChange, onSearch]
  )

  const columns = [
    {
      key: 'wallet_id',
      title: renderTitle('title-with-margin', 'Wallet ID'),
      dataIndex: 'wallet_id',
      filterDropdown: (
        <FilterInput
          idIdentifier='wallet_id'
          searchText={
            searchTextQuery.wallet_id ? searchTextQuery.wallet_id : undefined
          }
          onInputChange={(e) => onInputChange(e.target.value, 'wallet_id')}
          onSearch={(e) => onSearch(e, 'wallet_id')}
        />
      ),
      filterIcon: renderIcon(),
      filterDropdownVisible: filterActive?.wallet_id,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterActive({ ...filterActive, wallet_id: visible }),
      sorter: true,
      sortDirections: ['descend', 'ascend']
    },
    {
      key: 'partner_name',
      title: renderTitle('title-with-margin', 'Partner'),
      dataIndex: 'partner_name',
      render: (text, row) => (
        <div>{row?.partner_name || row?.partner_code}</div>
      ),
      filterDropdown: FilterDropdown('partner_code', 'partner_code_list'),
      filterIcon: renderIcon(),
      filterDropdownVisible: filterActive?.partner_code,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterActive({ ...filterActive, partner_code: visible })
    },
    {
      key: 'provider_name',
      title: renderTitle('title-with-margin', 'Provider'),
      dataIndex: 'provider_name',
      render: (text, row) => (
        <div>{row?.provider_name || row?.provider_code}</div>
      ),
      filterDropdown: FilterDropdown('provider_code', 'provider_code_list'),
      filterIcon: renderIcon(),
      filterDropdownVisible: filterActive?.provider_code,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterActive({ ...filterActive, provider_code: visible })
    },
    {
      key: 'product_name',
      title: renderTitle('title-with-margin', 'Product'),
      dataIndex: 'product_name',
      render: (text, row) => (
        <div>{row?.product_name || row?.product_code}</div>
      ),
      filterDropdown: FilterDropdown('product_code', 'partner_product_details'),
      filterIcon: renderIcon(),
      filterDropdownVisible: filterActive?.product_code,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterActive({ ...filterActive, product_code: visible })
    },
    {
      key: 'package_name',
      title: renderTitle('title-with-margin', 'Package Name'),
      dataIndex: 'package_name',
      filterDropdown: FilterDropdown('package_code', 'package_code_list'),
      filterIcon: renderIcon(),
      filterDropdownVisible: filterActive?.package_code,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterActive({ ...filterActive, package_code: visible })
    },
    {
      key: 'total_balance',
      title: renderTitle('title-without-margin', 'Balance (Rp)'),
      dataIndex: 'total_balance',
      render: (balance) => currencyChange(balance)
    },
    {
      key: 'detail',
      title: () => (
        <PermissionCheckerV2 requiredPermission='ops.aso_wallet_detail'>
          {renderTitle('title-without-margin', 'Detail')}
        </PermissionCheckerV2>
      ),
      render: (row) => (
        <PermissionCheckerV2 requiredPermission='ops.aso_wallet_detail'>
          <Icon
            type='eye'
            onClick={() => history.push(`aso-wallet/${row.wallet_id}`)}
            className='detail-icon'
            theme='filled'
          />
        </PermissionCheckerV2>
      )
    }
  ]

  const clearQuerySearchBuilder = useCallback(
    (identifier) => {
      const oldSearch = QueryString.parse(location?.search)
      delete oldSearch[identifier]
      const search = QuerySearchBuilder(oldSearch)
      history.push({ pathname: location?.pathname, search })
      return oldSearch
    },
    [location]
  )

  const clearFilter = useCallback(
    (identifier) => {
      const searchText = {
        ...searchTextQuery,
        [identifier]: undefined
      }
      setSearchTextQuery(searchText)
      setAppliedFilter(searchText)

      getMasterListRequest({
        query: {
          partnerCode: searchText.partner_code,
          productCode: searchText.product_code,
          packageCode: searchText.product_code,
          providerCode: searchText.provider_code
        }
      })
      const oldSearch = clearQuerySearchBuilder(identifier)
      fetch(oldSearch)
    },
    [
      searchTextQuery,
      clearQuerySearchBuilder,
      getMasterListRequest,
      setAppliedFilter,
      setSearchTextQuery
    ]
  )

  const fetch = useCallback(
    (params = {}) => {
      const { page } = params
      const pageNumber = Number(page) || 1
      delete params.page

      getWalletListRequest({
        query: {
          ...params,
          page_number: pageNumber
        }
      })
    },
    [getWalletListRequest]
  )

  const handlePageChange = useCallback(
    (pagination, filters, sorter) => {
      const { current } = pagination
      const querySearch = QueryString.parse(location?.search)
      const searchText = { ...querySearch, page: current }
      if (sorter?.field === 'wallet_id' && sorter?.order === 'descend') {
        searchText.sort = 'desc'
      } else if (sorter?.field === 'wallet_id' && sorter?.order === 'ascend') {
        searchText.sort = 'asc'
      } else {
        searchText.sort = undefined
      }
      const search = QuerySearchBuilder(searchText)
      history.push({ pathname: location?.pathname, search })
      fetch(searchText)
    },
    [QueryString, location]
  )

  const toggleModal = useCallback(
    (visible) => {
      showAddWalletModal(visible)
      if (visible) {
        getMasterListRequest()
      } else {
        getMasterListRequest({
          query: {
            partnerCode: appliedFilter.partner_code,
            productCode: appliedFilter.product_code,
            packageCode: appliedFilter.package_code,
            providerCode: appliedFilter.provider_code
          }
        })
      }
    },
    [showAddWalletModal, getMasterListRequest]
  )

  return (
    <LayoutContentWrapper className='referral-table'>
      <WalletListWrapper>
        <Spin spinning={GET_WALLET_LIST_LOADER || GET_MASTER_LIST_LOADER}>
          <Row type='flex' align='middle'>
            <Col sm={4} md={8}>
              <h3>
                <b>ASO Wallet</b>
              </h3>
            </Col>
            <PermissionCheckerV2 requiredPermission='ops.aso_wallet_add'>
              <Col sm={20} md={16}>
                <div
                  className='wallet-wrapper'
                  onClick={() => toggleModal(true)}
                >
                  <strong className='wallet-text'>Add New Wallet</strong>
                  <img src={WalletIcon} className='wallet-icon' alt='' />
                </div>
              </Col>
            </PermissionCheckerV2>
          </Row>
          <Divider />
          {appliedFilter &&
            Object.keys(appliedFilter).map((key, index) => {
              if (appliedFilter[key]) {
                return (
                  <Tag key={index} className='filter-tag' color='volcano'>
                    {WalletListFilterKeyMap[key]} - {appliedFilter[key]}
                    <span
                      className='remove-filter'
                      onClick={(e) => clearFilter(key)}
                    >
                      <Icon type='close' className='close' />
                    </span>
                  </Tag>
                )
              } else {
                return null
              }
            })}
          <TableWrapper
            columns={columns}
            rowKey={(record) => record.reference_id}
            dataSource={getWalletListData?.data}
            pagination={{
              pageSize: 10,
              total: Number(getWalletListData?.metadata?.total_count),
              current: getWalletListData?.metadata?.page_number
            }}
            onChange={handlePageChange}
            className='isoSearchableTable'
          />
          <AddWalletModal
            closeModal={() => toggleModal(false)}
            isOpen={isAddModalVisible}
            masterListData={getMasterListData}
            getMasterList={getMasterListRequest}
            addWalletRequest={addWalletRequest}
            ADD_WALLET_LOADER={ADD_WALLET_LOADER}
          />
        </Spin>
      </WalletListWrapper>
    </LayoutContentWrapper>
  )
}

export default Form.create({})(Wallet)
