import { Wallet } from './actions'

export const INITIAL_STATE = {}
const reducers = (state, action) => {
  const { payload } = action

  switch (action.type) {
    case Wallet.GET_WALLET_LIST:
    case Wallet.GET_MASTER_LIST:
    case Wallet.GET_WALLET_SUMMARY:
    case Wallet.ADD_WALLET:
    case Wallet.GET_WALLET_TRANSACTION:
    case Wallet.DEBIT_TOP_UP:
    case Wallet.ADD_TOP_UP:
      return { ...state, ...payload }
    case Wallet.EDIT_WALLET:
      return { ...state, ...payload }
    case Wallet.RESET_REDUX_STATE_AUDIT:
      if (payload && Array.isArray(payload)) {
        const stateToBeReset = {}
        payload.forEach(key => {
          stateToBeReset[key] = INITIAL_STATE[key]
        })
        return {
          ...state,
          ...stateToBeReset
        }
      } else {
        return {
          ...state
        }
      }
    default:
      return state
  }
}

export default reducers
